const input = $input.first().json;

const networkError =
  Boolean(input.error) ||
  typeof input.statusCode !== 'number' ||
  input.statusCode === 0;

if (networkError) {
  const message =
    (typeof input.error === 'object' && input.error && 'message' in input.error
      ? String(input.error.message)
      : null) ||
    (typeof input.message === 'string' ? input.message : null) ||
    'Sin conexión o timeout hacia el backend';

  return [
    {
      json: {
        statusCode: 503,
        body: {
          status: 'unavailable',
          reason: 'backend_unreachable',
          message,
        },
      },
    },
  ];
}

let payload = input.body;

if (typeof payload === 'string') {
  try {
    payload = JSON.parse(payload);
  } catch {
    return [
      {
        json: {
          statusCode: 502,
          body: {
            status: 'bad_gateway',
            reason: 'non_json_response',
            upstreamStatus: input.statusCode,
          },
        },
      },
    ];
  }
}

if (payload === null || typeof payload !== 'object') {
  return [
    {
      json: {
        statusCode: 502,
        body: {
          status: 'bad_gateway',
          reason: 'non_json_response',
          upstreamStatus: input.statusCode,
        },
      },
    },
  ];
}

return [
  {
    json: {
      statusCode: input.statusCode,
      body: payload,
    },
  },
];
